#!/usr/bin/env -S node_modules/.bin/ts-node
/**
 * import-maintained-apps-catalog — one-way sync from the reviewed
 * fleet-maintained-apps1 manifest output into the live maintained_apps /
 * maintained_app_versions tables (backend/migrations/011_add_windows_maintained_apps.sql).
 *
 * This is the "serving / runtime storage" sync step described in
 * WINDOWS_AGENT_PATCH_MANAGEMENT.md's server-side spec §2: the manifests
 * under fleet-maintained-apps1/outputs/*.json are the reviewed source of
 * truth (generated by that Go pipeline from winget manifests, or hand-written
 * custom_scripts overrides); this script is the "one-way import step... run
 * after a PR merges" it describes. Nothing should write into
 * maintained_app_versions.install_script/uninstall_script outside this path.
 *
 * Manifest shape (see fleet-maintained-apps1/manifest_writer.go's AppManifest):
 *   { slug, name, platform, package_identifier, unique_identifier,
 *     fuzzy_match_name, source, versions: [{ version, installer_url, sha256,
 *     upgrade_code?, install_script_ref, uninstall_script_ref, ... }],
 *     refs: { "<8-char-hash>": "<script text>" } }
 * install_script/uninstall_script are NOT inline — they're looked up via
 * refs[versions[0].install_script_ref] / refs[...uninstall_script_ref].
 *
 * Usage:
 *   npm run import:maintained-apps                       (default: ../fleet-maintained-apps1/outputs)
 *   npm run import:maintained-apps -- /path/to/outputs
 *
 * Idempotent: re-running upserts by slug/(app_id, version) — unchanged apps
 * no-op, a version bump adds a new maintained_app_versions row and flips
 * is_current, everything else about a version row is immutable once created
 * (never mutated in place, matching the audit-trail-friendly append style
 * used elsewhere in this codebase, e.g. patch_bundles) — with one narrow
 * exception: if an already-imported row's install_script/uninstall_script still
 * contains the known-bad $env:INSTALLER_PATH reference, a re-run repairs just
 * those two columns in place, so a stale import is never stuck behind an
 * unrelated version bump.
 */

import 'dotenv/config';
import * as fs from 'fs';
import * as path from 'path';
import { DataSource } from 'typeorm';
import { databaseConfig2 } from '../orm/config/ormconfig';
import { getLogger } from '../utils/logger';
import { SHA256_RE } from '../utils/patchBundle';

const logger = getLogger('scripts.importMaintainedAppsCatalog');

// fleet-maintained-apps1's script_generator.go carries over the upstream
// Fleet DM convention verbatim: every generated install/uninstall script
// reads the downloaded installer's path from `$env:INSTALLER_PATH`. The
// real Vajra Windows agent sets `$env:VAJRA_INSTALLER_PATH` instead (see
// WINDOWS_AGENT_PATCH_MANAGEMENT.md's wire contract — matches the existing
// VAJRA_ARG1/VAJRA_ARG2 convention). Since these scripts are sent to the
// agent unmodified (never templated server-side), importing them verbatim
// means $installerPath is always unset and every real install/uninstall
// fails immediately. Rewrite the variable reference at import time so what
// lands in maintained_app_versions actually matches what the agent sets.
// Idempotent: "$env:VAJRA_INSTALLER_PATH" does not itself contain the
// literal substring "$env:INSTALLER_PATH", so re-running this against an
// already-fixed script is a no-op. Matches both PowerShell reference forms —
// the bare `$env:INSTALLER_PATH` and the brace-disambiguated
// `${env:INSTALLER_PATH}` (the form actually emitted by script_generator.go
// for a number of generated scripts) — always replacing with the bare form,
// since VAJRA_INSTALLER_PATH doesn't need brace-disambiguation.
const WRONG_INSTALLER_PATH_ENV_VAR = /\$(?:env:INSTALLER_PATH\b|\{env:INSTALLER_PATH\})/gi;

function fixInstallerPathEnvVar(script: string, slug: string, kind: 'install' | 'uninstall'): string {
  if (!WRONG_INSTALLER_PATH_ENV_VAR.test(script)) return script;
  WRONG_INSTALLER_PATH_ENV_VAR.lastIndex = 0; // reset after .test() advanced it (global flag)
  const fixed = script.replace(WRONG_INSTALLER_PATH_ENV_VAR, '$env:VAJRA_INSTALLER_PATH');
  logger.warn(
    { slug, kind },
    'Rewrote $env:INSTALLER_PATH -> $env:VAJRA_INSTALLER_PATH in imported script to match the agent\'s actual wire contract',
  );
  return fixed;
}

interface AppManifestVersion {
  version: string;
  installer_url?: string;
  sha256?: string;
  install_script_ref: string;
  uninstall_script_ref: string;
  queries?: { exists?: string; patched?: string };
}

interface AppManifest {
  slug: string;
  name: string;
  platform: string;
  package_identifier?: string;
  unique_identifier: string;
  fuzzy_match_name: boolean;
  source?: string;
  versions: AppManifestVersion[];
  refs: Record<string, string>;
}

interface AppsIndexEntry {
  slug: string;
  manifest_file: string;
}

interface AppsIndex {
  count: number;
  apps: AppsIndexEntry[];
}

/** slugs in fleet-maintained-apps1 carry a "/windows" suffix — stored without it. */
function normalizeSlug(rawSlug: string): string {
  return rawSlug.replace(/\/windows$/i, '');
}

/** Best-effort extraction of the publisher baked into the generated `exists`
 * SQL (`AND publisher = '...'`) — not a first-class manifest field (see
 * fleet-maintained-apps1's NormalizedApp vs AppManifest split). Null if the
 * pattern isn't found (custom-script apps' queries may not follow it). */
function extractPublisher(existsQuery: string | undefined): string | null {
  if (!existsQuery) return null;
  const m = existsQuery.match(/publisher\s*=\s*'([^']*)'/i);
  return m ? m[1].replace(/''/g, "'") : null;
}

function loadJson<T>(filePath: string): T {
  return JSON.parse(fs.readFileSync(filePath, 'utf8')) as T;
}

async function importCatalog(outputsDir: string): Promise<void> {
  const indexPath = path.join(outputsDir, 'apps.json');
  if (!fs.existsSync(indexPath)) {
    throw new Error(`apps.json not found at ${indexPath} — pass the fleet-maintained-apps1/outputs directory`);
  }
  const index = loadJson<AppsIndex>(indexPath);
  logger.info({ outputsDir, count: index.count }, 'Loaded maintained-apps index');

  const dataSource = new DataSource(databaseConfig2 as any);
  await dataSource.initialize();

  let imported = 0;
  let skipped = 0;
  let versionsAdded = 0;
  let scriptsRepaired = 0;

  try {
    for (const entry of index.apps) {
      const manifestPath = path.join(outputsDir, entry.manifest_file);
      let manifest: AppManifest;
      try {
        manifest = loadJson<AppManifest>(manifestPath);
      } catch (err) {
        logger.warn({ err, manifestPath }, 'Skipping app: manifest could not be read/parsed');
        skipped++;
        continue;
      }

      const version = manifest.versions?.[0];
      if (!version) {
        logger.warn({ slug: manifest.slug }, 'Skipping app: no versions in manifest');
        skipped++;
        continue;
      }

      let installScript = manifest.refs?.[version.install_script_ref];
      let uninstallScript = manifest.refs?.[version.uninstall_script_ref];
      if (!installScript || !uninstallScript) {
        logger.warn(
          { slug: manifest.slug, install_script_ref: version.install_script_ref, uninstall_script_ref: version.uninstall_script_ref },
          'Skipping app: install/uninstall script ref did not resolve in refs map',
        );
        skipped++;
        continue;
      }
      installScript = fixInstallerPathEnvVar(installScript, manifest.slug, 'install');
      uninstallScript = fixInstallerPathEnvVar(uninstallScript, manifest.slug, 'uninstall');

      let sha256 = version.sha256 ? version.sha256.toLowerCase() : null;
      if (sha256 && !SHA256_RE.test(sha256)) {
        logger.warn({ slug: manifest.slug, sha256 }, 'Malformed sha256 in manifest, dropping it rather than importing a bad checksum');
        sha256 = null;
      }
      // installer_url and sha256 must travel together, same rule the agent
      // enforces — a URL with no checksum to verify it against is unusable.
      const installerUrl = version.installer_url && sha256 ? version.installer_url : null;
      const finalSha256 = installerUrl ? sha256 : null;

      const slug = normalizeSlug(manifest.slug);
      const publisher = extractPublisher(version.queries?.exists);

      await dataSource.transaction(async (mgr) => {
        const appRows = await mgr.query(
          `INSERT INTO maintained_apps
             (slug, name, publisher, platform, package_identifier, display_name_match, fuzzy_match_name, is_active)
           VALUES ($1,$2,$3,$4,$5,$6,$7,true)
           ON CONFLICT (slug) DO UPDATE SET
             name = EXCLUDED.name,
             publisher = COALESCE(EXCLUDED.publisher, maintained_apps.publisher),
             package_identifier = EXCLUDED.package_identifier,
             display_name_match = EXCLUDED.display_name_match,
             fuzzy_match_name = EXCLUDED.fuzzy_match_name,
             updated_at = NOW()
           RETURNING id`,
          [slug, manifest.name, publisher, manifest.platform || 'windows', manifest.package_identifier ?? null, manifest.unique_identifier, !!manifest.fuzzy_match_name],
        );
        const appId = appRows[0].id as number;

        const existing = await mgr.query(
          `SELECT id, install_script, uninstall_script FROM maintained_app_versions WHERE maintained_app_id = $1 AND version = $2`,
          [appId, version.version],
        );

        if (existing.length === 0) {
          await mgr.query(`UPDATE maintained_app_versions SET is_current = false WHERE maintained_app_id = $1`, [appId]);
          await mgr.query(
            `INSERT INTO maintained_app_versions
               (maintained_app_id, version, installer_url, sha256, install_script, uninstall_script, is_current, source_ref)
             VALUES ($1,$2,$3,$4,$5,$6,true,$7)`,
            [appId, version.version, installerUrl, finalSha256, installScript, uninstallScript, entry.slug],
          );
          versionsAdded++;
        } else {
          // Same version already present — normally left immutable, except
          // for repairing the known $env:INSTALLER_PATH bug: if the stored
          // scripts still carry the pre-fix reference (imported by an older
          // copy of fixInstallerPathEnvVar), rewrite just those two columns
          // to the current, correctly-rewritten script text.
          const existingRow = existing[0];
          WRONG_INSTALLER_PATH_ENV_VAR.lastIndex = 0;
          const installStale = WRONG_INSTALLER_PATH_ENV_VAR.test(existingRow.install_script);
          WRONG_INSTALLER_PATH_ENV_VAR.lastIndex = 0;
          const uninstallStale = WRONG_INSTALLER_PATH_ENV_VAR.test(existingRow.uninstall_script);
          WRONG_INSTALLER_PATH_ENV_VAR.lastIndex = 0;
          if (installStale || uninstallStale) {
            await mgr.query(
              `UPDATE maintained_app_versions SET install_script = $2, uninstall_script = $3 WHERE id = $1`,
              [existingRow.id, installScript, uninstallScript],
            );
            scriptsRepaired++;
            logger.warn(
              { slug, versionId: existingRow.id },
              'Repaired stale $env:INSTALLER_PATH reference in an already-imported maintained_app_versions row',
            );
          }
          // Just make sure it (and only it) is flagged current, in case a
          // prior partial run left it stale.
          await mgr.query(`UPDATE maintained_app_versions SET is_current = (id = $2) WHERE maintained_app_id = $1`, [appId, existingRow.id]);
        }
      });

      imported++;
    }

    logger.info({ imported, skipped, versionsAdded, scriptsRepaired }, 'Maintained-apps catalog import complete');
  } finally {
    await dataSource.destroy();
  }
}

if (require.main === module) {
  const argDir = process.argv[2];
  const outputsDir = argDir
    ? path.resolve(argDir)
    : path.resolve(__dirname, '../../../fleet-maintained-apps1/outputs');

  importCatalog(outputsDir)
    .then(() => process.exit(0))
    .catch((err) => {
      logger.error({ err }, 'Maintained-apps catalog import failed');
      process.exit(1);
    });
}

export { importCatalog };
